"""Deterministic spending alerts generated by TIANA's own budget rules.

These alerts do not call the AI provider. The AI coach is reserved for
personalized recommendations and questions from the user.
"""
from budgets.models import Budget
from budgets.services import attach_budget_spending
from .models import Notification


ALERT_THRESHOLDS = (80, 100)


def evaluate_spending_alerts(user, budgets=None):
    """Create deduplicated alerts after one aggregate for all budget totals."""
    created = []
    if budgets is None:
        budgets = Budget.objects.filter(owner=user)
    budgets = attach_budget_spending(budgets, owner=user)

    for budget in budgets:
        amount = budget.amount
        if amount <= 0:
            continue

        spent = budget.spent_amount
        percent = float(spent / amount * 100)
        if percent < ALERT_THRESHOLDS[0]:
            continue

        window_start, window_end = budget._current_window()
        if window_end < window_start:
            continue

        label = (budget.category or budget.name or "category").strip()
        for threshold in ALERT_THRESHOLDS:
            if percent < threshold:
                continue

            dedupe_key = f"budget:{budget.pk}:{budget.period}:{window_start:%Y%m%d}:{threshold}"
            if threshold == 100:
                title = f"{label} budget reached"
                message = (
                    f"You've used {spent:,.0f} of {amount:,.0f} {budget.currency} "
                    f"in your {budget.get_period_display().lower()} {label.lower()} budget. "
                    "Further spending will take you over the limit."
                )
            else:
                title = f"{label} budget getting close"
                message = (
                    f"You've used {spent:,.0f} of {amount:,.0f} {budget.currency} "
                    f"({percent:.0f}%) in your {budget.get_period_display().lower()} "
                    f"{label.lower()} budget."
                )

            notification, was_created = Notification.objects.get_or_create(
                user=user,
                dedupe_key=dedupe_key,
                defaults={
                    "title": title,
                    "message": message,
                    "kind": "warning",
                    "source": "system",
                },
            )
            if was_created:
                created.append(notification)

    return created
